//! cTrader Open API messages: Spotware's protobuf types (generated by
//! `build.rs` from `proto/`), the payload type of each message the adapter
//! sends or reads, and the `ProtoMessage` envelope every frame is.
//!
//! A frame is one binary WebSocket message holding one `ProtoMessage`: the
//! payload type, the encoded message, and the `clientMsgId` the request set
//! and its response echoes (help.ctrader.com/open-api, "Send and receive
//! Protobuf messages"). Errors come back as `ProtoOAErrorRes` (or the
//! proxy's `ProtoErrorRes`) under the request's `clientMsgId`.

use std::fmt;

use prost::Message as _;
use zeroize::Zeroize;

#[allow(clippy::all, clippy::pedantic, missing_docs, dead_code)]
mod proto {
    include!(concat!(env!("OUT_DIR"), "/ctrader_open_api.rs"));
}

pub(super) use proto::{
    ProtoErrorRes, ProtoHeartbeatEvent, ProtoMessage, ProtoOaAccountAuthReq, ProtoOaAccountAuthRes,
    ProtoOaAccountType, ProtoOaAccountsTokenInvalidatedEvent, ProtoOaApplicationAuthReq,
    ProtoOaApplicationAuthRes, ProtoOaAsset, ProtoOaAssetListReq, ProtoOaAssetListRes, ProtoOaDeal,
    ProtoOaDealListReq, ProtoOaDealListRes, ProtoOaDealStatus, ProtoOaErrorRes,
    ProtoOaGetTickDataReq, ProtoOaGetTickDataRes, ProtoOaLightSymbol, ProtoOaOrder,
    ProtoOaOrderListReq, ProtoOaOrderListRes, ProtoOaOrderStatus, ProtoOaOrderTriggerMethod,
    ProtoOaOrderType, ProtoOaPayloadType, ProtoOaPosition, ProtoOaPositionStatus, ProtoOaQuoteType,
    ProtoOaReconcileReq, ProtoOaReconcileRes, ProtoOaSpotEvent, ProtoOaSubscribeSpotsReq,
    ProtoOaSubscribeSpotsRes, ProtoOaSymbol, ProtoOaSymbolByIdReq, ProtoOaSymbolByIdRes,
    ProtoOaSymbolsListReq, ProtoOaSymbolsListRes, ProtoOaTickData, ProtoOaTimeInForce,
    ProtoOaTradeSide, ProtoOaTrader, ProtoOaTraderReq, ProtoOaTraderRes,
    ProtoOaUnsubscribeSpotsReq, ProtoOaUnsubscribeSpotsRes, ProtoPayloadType,
};

// The synthetic positions and deals of the tests are built from these.
#[cfg(test)]
pub(super) use proto::{ProtoOaClosePositionDetail, ProtoOaTradeData};

/// A message and the payload type it travels under.
pub(super) trait Payload: prost::Message + Default {
    /// The `payloadType` of the envelope.
    const TYPE: u32;
}

macro_rules! payload {
    ($($message:ident => $payload_type:expr),* $(,)?) => {
        $(impl Payload for $message {
            const TYPE: u32 = $payload_type as u32;
        })*
    };
}

payload! {
    ProtoHeartbeatEvent => ProtoPayloadType::HeartbeatEvent,
    ProtoErrorRes => ProtoPayloadType::ErrorRes,
    ProtoOaErrorRes => ProtoOaPayloadType::ProtoOaErrorRes,
    ProtoOaApplicationAuthReq => ProtoOaPayloadType::ProtoOaApplicationAuthReq,
    ProtoOaApplicationAuthRes => ProtoOaPayloadType::ProtoOaApplicationAuthRes,
    ProtoOaAccountAuthReq => ProtoOaPayloadType::ProtoOaAccountAuthReq,
    ProtoOaAccountAuthRes => ProtoOaPayloadType::ProtoOaAccountAuthRes,
    ProtoOaAccountsTokenInvalidatedEvent => ProtoOaPayloadType::ProtoOaAccountsTokenInvalidatedEvent,
    ProtoOaAssetListReq => ProtoOaPayloadType::ProtoOaAssetListReq,
    ProtoOaAssetListRes => ProtoOaPayloadType::ProtoOaAssetListRes,
    ProtoOaSymbolsListReq => ProtoOaPayloadType::ProtoOaSymbolsListReq,
    ProtoOaSymbolsListRes => ProtoOaPayloadType::ProtoOaSymbolsListRes,
    ProtoOaSymbolByIdReq => ProtoOaPayloadType::ProtoOaSymbolByIdReq,
    ProtoOaSymbolByIdRes => ProtoOaPayloadType::ProtoOaSymbolByIdRes,
    ProtoOaGetTickDataReq => ProtoOaPayloadType::ProtoOaGetTickdataReq,
    ProtoOaGetTickDataRes => ProtoOaPayloadType::ProtoOaGetTickdataRes,
    ProtoOaSubscribeSpotsReq => ProtoOaPayloadType::ProtoOaSubscribeSpotsReq,
    ProtoOaSubscribeSpotsRes => ProtoOaPayloadType::ProtoOaSubscribeSpotsRes,
    ProtoOaUnsubscribeSpotsReq => ProtoOaPayloadType::ProtoOaUnsubscribeSpotsReq,
    ProtoOaUnsubscribeSpotsRes => ProtoOaPayloadType::ProtoOaUnsubscribeSpotsRes,
    ProtoOaSpotEvent => ProtoOaPayloadType::ProtoOaSpotEvent,
    ProtoOaTraderReq => ProtoOaPayloadType::ProtoOaTraderReq,
    ProtoOaTraderRes => ProtoOaPayloadType::ProtoOaTraderRes,
    ProtoOaReconcileReq => ProtoOaPayloadType::ProtoOaReconcileReq,
    ProtoOaReconcileRes => ProtoOaPayloadType::ProtoOaReconcileRes,
    ProtoOaDealListReq => ProtoOaPayloadType::ProtoOaDealListReq,
    ProtoOaDealListRes => ProtoOaPayloadType::ProtoOaDealListRes,
    ProtoOaOrderListReq => ProtoOaPayloadType::ProtoOaOrderListReq,
    ProtoOaOrderListRes => ProtoOaPayloadType::ProtoOaOrderListRes,
}

/// Whether a request of `payload_type` counts against cTrader's limit of
/// historical requests (5 a second per connection): the tick requests, and
/// the deal list, history too (Spotware's docs name no list of either
/// kind, so it is held to the lower limit).
pub(super) fn is_historical(payload_type: u32) -> bool {
    payload_type == ProtoOaGetTickDataReq::TYPE || payload_type == ProtoOaDealListReq::TYPE
}

/// The name of a payload type, as the `.proto` files spell it, or its
/// number if no enum knows it.
pub(super) fn payload_name(payload_type: u32) -> String {
    let known = i32::try_from(payload_type).ok().and_then(|n| {
        ProtoOaPayloadType::try_from(n)
            .map(|t| t.as_str_name())
            .or_else(|_| ProtoPayloadType::try_from(n).map(|t| t.as_str_name()))
            .ok()
    });
    known.map_or_else(|| payload_type.to_string(), str::to_owned)
}

/// The frame of `message`, tagged `client_msg_id` when it is a request.
pub(super) fn frame<M: Payload>(message: &M, client_msg_id: Option<String>) -> Vec<u8> {
    ProtoMessage {
        payload_type: M::TYPE,
        payload: Some(message.encode_to_vec()),
        client_msg_id,
    }
    .encode_to_vec()
}

/// As `frame`, for a message holding secret material: the encoded copy
/// of the message is wiped once the frame holds it. The frame itself goes
/// to the transport, out of the adapter's reach.
pub(super) fn secret_frame<M: Payload>(message: &M, client_msg_id: Option<String>) -> Vec<u8> {
    let mut envelope = ProtoMessage {
        payload_type: M::TYPE,
        payload: Some(message.encode_to_vec()),
        client_msg_id,
    };
    let frame = envelope.encode_to_vec();
    envelope.payload.zeroize();
    frame
}

/// The message `envelope` holds: an `M`, or the error cTrader answered.
pub(super) fn open<M: Payload>(envelope: &ProtoMessage) -> Result<M, IcError> {
    let payload = envelope.payload.as_deref().unwrap_or_default();
    let malformed = |e: prost::DecodeError| {
        IcError::Protocol(format!(
            "malformed {}: {e}",
            payload_name(envelope.payload_type)
        ))
    };
    match envelope.payload_type {
        t if t == M::TYPE => M::decode(payload).map_err(malformed),
        t if t == ProtoOaErrorRes::TYPE => {
            let error = ProtoOaErrorRes::decode(payload).map_err(malformed)?;
            Err(IcError::Venue {
                code: error.error_code,
                description: error.description,
            })
        }
        t if t == ProtoErrorRes::TYPE => {
            let error = ProtoErrorRes::decode(payload).map_err(malformed)?;
            Err(IcError::Venue {
                code: error.error_code,
                description: error.description,
            })
        }
        other => Err(IcError::Protocol(format!(
            "expected {}, got {}",
            payload_name(M::TYPE),
            payload_name(other)
        ))),
    }
}

/// Why a request to cTrader failed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) enum IcError {
    /// cTrader answered with an error: its code (a `ProtoOAErrorCode` or
    /// `ProtoErrorCode` name) and description.
    Venue {
        code: String,
        description: Option<String>,
    },
    /// The session cannot serve requests: authentication failed, or
    /// cTrader ended it.
    Session(String),
    /// The connection closed, or was replaced, before the response.
    ConnectionLost,
    /// No response within the request timeout.
    Timeout,
    /// The frame could not be sent.
    Transport(String),
    /// A response that is not the expected message.
    Protocol(String),
}

impl fmt::Display for IcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Venue {
                code,
                description: Some(description),
            } => write!(f, "cTrader error {code}: {description}"),
            Self::Venue {
                code,
                description: None,
            } => write!(f, "cTrader error {code}"),
            Self::Session(reason) => write!(f, "no cTrader session: {reason}"),
            Self::ConnectionLost => f.write_str("the cTrader connection was lost"),
            Self::Timeout => f.write_str("cTrader did not answer in time"),
            Self::Transport(e) => write!(f, "sending to cTrader: {e}"),
            Self::Protocol(e) => write!(f, "unexpected cTrader response: {e}"),
        }
    }
}

impl std::error::Error for IcError {}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::data::ic::testing::SYMBOL_BY_ID_UNKNOWN;

    fn envelope<M: Payload>(message: &M) -> ProtoMessage {
        ProtoMessage::decode(frame(message, Some("7".to_owned())).as_slice()).unwrap()
    }

    #[test]
    fn a_frame_is_the_envelope_of_the_message_and_its_id() {
        let request = ProtoOaSymbolByIdReq {
            ctid_trader_account_id: 1_000_001,
            symbol_id: vec![1, 41],
            ..Default::default()
        };

        let envelope = envelope(&request);

        assert_eq!(envelope.payload_type, 2116);
        assert_eq!(envelope.client_msg_id.as_deref(), Some("7"));
        assert_eq!(open::<ProtoOaSymbolByIdReq>(&envelope), Ok(request));
    }

    #[test]
    fn a_secret_frame_is_the_same_frame() {
        let request = ProtoOaApplicationAuthReq {
            client_id: "12345_clientIdValue".to_owned(),
            client_secret: "clientSecretValue".to_owned(),
            ..Default::default()
        };

        assert_eq!(
            secret_frame(&request, Some("1".to_owned())),
            frame(&request, Some("1".to_owned()))
        );
    }

    /// The error is the fixture `symbol_by_id_unknown`.
    #[test]
    fn an_error_response_opens_as_the_venue_error() {
        let envelope = ProtoMessage {
            payload_type: ProtoOaErrorRes::TYPE,
            payload: Some(SYMBOL_BY_ID_UNKNOWN.to_vec()),
            client_msg_id: Some("7".to_owned()),
        };

        let opened = open::<ProtoOaSymbolByIdRes>(&envelope);

        assert_eq!(
            opened,
            Err(IcError::Venue {
                code: "SYMBOL_NOT_FOUND".to_owned(),
                description: Some("No symbols with requested ID".to_owned()),
            })
        );
    }

    #[test]
    fn a_proxy_error_response_opens_as_the_venue_error() {
        let error = ProtoErrorRes {
            error_code: "BLOCKED_PAYLOAD_TYPE".to_owned(),
            ..Default::default()
        };

        let opened = open::<ProtoOaAssetListRes>(&envelope(&error));

        assert_eq!(
            opened,
            Err(IcError::Venue {
                code: "BLOCKED_PAYLOAD_TYPE".to_owned(),
                description: None,
            })
        );
    }

    #[test]
    fn another_message_is_a_protocol_error_naming_both() {
        let opened = open::<ProtoOaAssetListRes>(&envelope(&ProtoOaSymbolsListRes::default()));

        assert_eq!(
            opened,
            Err(IcError::Protocol(
                "expected PROTO_OA_ASSET_LIST_RES, got PROTO_OA_SYMBOLS_LIST_RES".to_owned()
            ))
        );
    }

    /// Synthetic: bytes that are no protobuf message.
    #[test]
    fn a_malformed_payload_is_a_protocol_error() {
        let envelope = ProtoMessage {
            payload_type: ProtoOaAssetListRes::TYPE,
            payload: Some(vec![0xff, 0xff, 0xff]),
            client_msg_id: None,
        };

        let opened = open::<ProtoOaAssetListRes>(&envelope);

        assert!(
            matches!(&opened, Err(IcError::Protocol(e)) if e.starts_with("malformed PROTO_OA_ASSET_LIST_RES")),
            "{opened:?}"
        );
    }

    #[test]
    fn tick_and_deal_requests_are_historical_others_not() {
        assert!(is_historical(ProtoOaGetTickDataReq::TYPE));
        assert!(is_historical(ProtoOaDealListReq::TYPE));
        assert!(!is_historical(ProtoOaReconcileReq::TYPE));
        assert!(!is_historical(ProtoOaSymbolByIdReq::TYPE));
    }

    #[test]
    fn an_unknown_payload_type_is_named_by_its_number() {
        assert_eq!(payload_name(2131), "PROTO_OA_SPOT_EVENT");
        assert_eq!(payload_name(51), "HEARTBEAT_EVENT");
        assert_eq!(payload_name(9999), "9999");
    }
}
